import { AlertCircle, ArrowLeft, Bot, Send, UserIcon } from "lucide-react";
import { formatDate, truncate } from "../../utils/formatDate";
import TypingAssistantMessage from "./TypingAssistantMessage";
import { toast } from "../ui/toast";
import { useCallback, useEffect, useRef, useState } from "react";
import type { ChatMessage } from "../../api/chatApi";
import { useQuery } from "@tanstack/react-query";
import getCurrentUser from "../../utils/getUser";
import { getMediaUrl } from "../../utils/getMediaUrl";

// ── Panneau de conversation ──────────────────────────────────────────────
interface AssistantChatPanelProps {
  conversationId: number;
  messages: ChatMessage[];
  isLoadingMessages: boolean;
  isSending: boolean;
  sendError: Error | null;
  onSend: (content: string) => void;
  onBack: () => void;
  mobile: boolean;
  optimisticMessage?: string;
}

const AssistantChatPanel: React.FC<AssistantChatPanelProps> = ({
  conversationId,
  messages,
  isLoadingMessages,
  isSending,
  sendError,
  onSend,
  onBack,
  mobile,
  optimisticMessage,
}) => {
  const [input, setInput] = useState('');
  const [localTypingId, setLocalTypingId] = useState<number | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const { data: user } = useQuery({
      queryKey: ["currentUser"],
      queryFn: getCurrentUser,
      retry: false,
    });

  const displayMessages: (ChatMessage & { _optimistic?: boolean })[] = [...messages];

  if (optimisticMessage && isSending) {
    displayMessages.push({
      id: -1,
      role: 'utilisateur',
      content: optimisticMessage,
      created_at: new Date().toISOString(),
      _optimistic: true,
    } as any);
  }

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [displayMessages.length, isSending]);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 120)}px`;
    }
  }, [input]);

  useEffect(() => {
    if (!isSending && messages.length > 0) {
      const last = messages[messages.length - 1];
      if (last.role === 'assistant') {
        setLocalTypingId(last.id);
      }
    }
  }, [isSending, messages]);

  const handleSubmit = useCallback(() => {
    const trimmed = input.trim();
    if (!trimmed || isSending) return;
    if (trimmed.length > 2000) {
      toast.add({
        title: 'Message trop long',
        description: 'Le message ne doit pas dépasser 2000 caractères.',
        type: 'error',
      });
      return;
    }
    onSend(trimmed);
    setInput('');
  }, [input, isSending, onSend]);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    const isCoarsePointer =
      typeof window !== 'undefined' && window.matchMedia?.('(pointer: coarse)').matches;
    if (e.key === 'Enter' && !e.shiftKey && !isCoarsePointer) {
      e.preventDefault();
      handleSubmit();
    }
  };

  const convTitle =
    displayMessages.find((m) => m.role === 'utilisateur')?.content ||
    `Conversation #${conversationId}`;

  return (
    <div className="flex h-full relative min-h-0 flex-col w-full bg-white">
      {mobile && (
        <button
          type="button"
          onClick={onBack}
          className="flex shrink-0 items-center gap-2 border-b border-brand-ink/8 bg-white px-4 py-3 text-sm font-medium text-muted-foreground hover:bg-brand-sand/40 md:hidden"
        >
          <ArrowLeft className="h-4 w-4" />
          Retour
        </button>
      )}

      <div className="flex shrink-0 items-center gap-3 border-b border-brand-ink/8 bg-white px-4 py-3">
        <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-brand-ink">
          <Bot className="h-4.5 w-4.5 text-brand-green" />
        </div>
        <div className="min-w-0 flex-1">
