import { useEffect, useRef, useState } from "react";

// ── Effet de frappe pour les réponses de l'assistant ────────────────────
interface TypingAssistantMessageProps {
  fullText: string;
  onComplete?: () => void;
}

const TypingAssistantMessage: React.FC<TypingAssistantMessageProps> = ({
  fullText,
  onComplete,
}) => {
  const [displayed, setDisplayed] = useState('');
  const indexRef = useRef(0);

  useEffect(() => {
    if (!fullText) return;
    indexRef.current = 0;
    setDisplayed('');
    const timer = setInterval(() => {
      indexRef.current += 1;
      if (indexRef.current >= fullText.length) {
        setDisplayed(fullText);
        clearInterval(timer);
        onComplete?.();
      } else {
        setDisplayed(fullText.slice(0, indexRef.current));
      }
    }, 15);
    return () => clearInterval(timer);
  }, [fullText, onComplete]);

  return (
    <div className="whitespace-pre-wrap break-words">
      {displayed}
      {displayed.length < fullText.length && (
        <span className="ml-1 inline-block h-4 w-1 animate-pulse bg-brand-green" />
      )}
    </div>
  );
};


export default TypingAssistantMessage;

import React, { useState, useRef, useEffect } from 'react';
import { Send, Smile, Mic, Trash2, Square } from 'lucide-react';

interface MessageInputProps {
  onSendMessage: (content: string) => void;
  onSendAudioMessage?: (audioUrl: string) => void;
  isSending: boolean;
  disabled?: boolean;
}

const MessageInput: React.FC<MessageInputProps> = ({
  onSendMessage,
  onSendAudioMessage,
  isSending,
  disabled = false,
}) => {
  const [message, setMessage] = useState('');
  const [isRecording, setIsRecording] = useState(false);
  const [recordingSeconds, setRecordingSeconds] = useState(0);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  // Auto-resize textarea
  useEffect(() => {
    const textarea = textareaRef.current;
    if (textarea) {
      textarea.style.height = 'auto';
      textarea.style.height = `${Math.min(textarea.scrollHeight, 120)}px`;
    }
  }, [message]);

  // Clean up timer on unmount
  useEffect(() => {
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, []);

  const handleSend = () => {
    const trimmed = message.trim();
    if (!trimmed || isSending || disabled) return;
    onSendMessage(trimmed);
    setMessage('');
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const shouldSendRef = useRef(false);

  // ── Audio Recording Logic ──
  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      audioChunksRef.current = [];
      shouldSendRef.current = false;
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;

      mediaRecorder.ondataavailable = (event) => {
        if (event.data && event.data.size > 0) {
          audioChunksRef.current.push(event.data);
        }
      };

      mediaRecorder.onstop = () => {
        if (shouldSendRef.current) {
          const mimeType = mediaRecorder.mimeType || 'audio/webm';
          const audioBlob = new Blob(audioChunksRef.current, { type: mimeType });
          const reader = new FileReader();

          reader.onloadend = () => {
            const base64Audio = reader.result as string;
            if (onSendAudioMessage && base64Audio) {
              onSendAudioMessage(base64Audio);
            }
          };

          reader.readAsDataURL(audioBlob);
        }

        // Clean up tracks
        stream.getTracks().forEach((track) => track.stop());
        setIsRecording(false);
        setRecordingSeconds(0);
        audioChunksRef.current = [];
        shouldSendRef.current = false;
      };

      mediaRecorder.start(100);
      setIsRecording(true);
      setRecordingSeconds(0);

      if (timerRef.current) clearInterval(timerRef.current);
      timerRef.current = setInterval(() => {
        setRecordingSeconds((prev) => prev + 1);
      }, 1000);
    } catch (err) {
      console.error("Accès au microphone refusé ou non supporté:", err);
      alert("Impossible d'accéder au microphone.");
    }
  };

  const cancelRecording = () => {
    shouldSendRef.current = false;
    if (timerRef.current) clearInterval(timerRef.current);

    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
    } else {
      setIsRecording(false);
      setRecordingSeconds(0);
      audioChunksRef.current = [];
    }
  };

  const stopAndSendRecording = () => {
    shouldSendRef.current = true;
    if (timerRef.current) clearInterval(timerRef.current);

    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
    }
  };

  const formatRecordingTime = (secs: number) => {
    const m = Math.floor(secs / 60);
    const s = secs % 60;
    return `${m < 10 ? '0' : ''}${m}:${s < 10 ? '0' : ''}${s}`;
  };

  const canSend = message.trim().length > 0 && !isSending && !disabled;

  if (disabled) {
    return (
      <div className="px-4 py-3 bg-brand-canvas border-t border-border/80 shrink-0">
        <div className="flex items-center justify-center gap-2 py-2 px-3 bg-amber-500/10 border border-amber-500/20 rounded-xl text-amber-700 text-[12px]">
          <span className="font-medium">
            L'envoi de message est désactivé car aucune mission active ne vous lie à cet utilisateur.
          </span>
        </div>
      </div>
    );
  }

  return (
    <div className="px-4 py-3 bg-white border-t border-border shrink-0">
      {isRecording ? (
        /* ── Audio Recording UI ── */
        <div className="flex items-center gap-3 bg-red-50/80 border border-red-200 rounded-2xl px-4 py-2">
          {/* Pulsing red dot */}
          <div className="relative flex items-center justify-center shrink-0">
            <span className="absolute w-3 h-3 bg-red-500 rounded-full animate-ping opacity-75" />
            <span className="w-2.5 h-2.5 bg-red-600 rounded-full" />
          </div>

          {/* Recording timer */}
          <span className="text-[12px] font-mono font-bold text-red-700 shrink-0">
            {formatRecordingTime(recordingSeconds)}
          </span>

          {/* Animated sound wave bars */}
          <div className="flex-1 flex items-center justify-center gap-1 h-5 px-2 overflow-hidden">
            {[40, 80, 50, 90, 30, 70, 100, 60, 80, 40, 90, 50, 70, 30, 60].map((h, i) => (
              <span
                key={i}
                className="w-1 bg-red-400/60 rounded-full animate-pulse"
                style={{
                  height: `${h}%`,
                  animationDuration: `${0.4 + (i % 5) * 0.1}s`,
                }}
              />
            ))}
          </div>

          {/* Cancel button */}
          <button
            type="button"
            onClick={cancelRecording}
            className="p-1.5 rounded-full text-muted-foreground hover:text-red-600 hover:bg-red-100 transition-colors cursor-pointer shrink-0"
            title="Annuler l'enregistrement"
          >
            <Trash2 className="w-4 h-4" />
          </button>

          {/* Send Audio button */}
          <button
            type="button"
            onClick={stopAndSendRecording}
            className="w-8 h-8 rounded-full bg-red-600 hover:bg-red-700 text-white flex items-center justify-center transition-transform active:scale-95 cursor-pointer shrink-0"
            title="Envoyer le message vocal"
          >
            <Send className="w-3.5 h-3.5" style={{ transform: 'translateX(1px)' }} />
          </button>
        </div>
      ) : (
        /* ── Standard Text Input UI ── */
        <div className="flex items-end gap-2">
          <div className="flex-1 flex items-end bg-brand-canvas/80 border border-border/80 rounded-2xl px-3.5 py-1.5 transition-all focus-within:border-brand-violet/30 focus-within:ring-1.5 focus-within:ring-brand-violet/10">
            <textarea
              ref={textareaRef}
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Ecrivez votre message..."
              rows={1}
              disabled={disabled}
              className="flex-1 bg-transparent text-[12.5px] text-brand-ink placeholder:text-muted-foreground resize-none focus:outline-none min-h-[28px] max-h-[120px] py-1 leading-snug"
            />

            {/* Emoji button */}
            <button
              type="button"
              className="p-1 text-muted-foreground hover:text-neutral-600 transition-colors cursor-pointer shrink-0 mb-0.5"
              title="Emoji"
            >
              <Smile className="w-4.5 h-4.5" strokeWidth={1.6} />
            </button>
          </div>

          {/* Microphone button (when message is empty) or Send button (when message is typed) */}
          {message.trim().length === 0 ? (
            <button
              type="button"
              onClick={startRecording}
              disabled={disabled}
              className="w-9 h-9 rounded-full bg-brand-violet hover:bg-brand-violet text-white flex items-center justify-center transition-all duration-200 shrink-0 cursor-pointer shadow-sm active:scale-95 disabled:opacity-50"
              title="Enregistrer un message vocal"
            >
              <Mic className="w-4 h-4" strokeWidth={2} />
            </button>
          ) : (
            <button
              type="button"
              onClick={handleSend}
              disabled={!canSend}
              className={`
                w-9 h-9 rounded-full flex items-center justify-center transition-all duration-200 shrink-0 cursor-pointer
                ${canSend
                  ? 'bg-brand-green hover:bg-brand-green-hover text-brand-ink shadow-md shadow-brand-green/20 hover:shadow-lg hover:shadow-brand-green/30 active:scale-95'
                  : 'bg-neutral-200 text-muted-foreground cursor-not-allowed'
                }
              `}
              title="Envoyer"
            >
              <Send className="w-4 h-4" strokeWidth={2} style={{ transform: 'translateX(1px)' }} />
            </button>
          )}
        </div>
      )}
    </div>
  );
};

export default MessageInput;

import React, { useState } from 'react';
import { X, Lock, Loader2, CheckCircle2 } from 'lucide-react';
import { changePassword } from '../../api/userApi';

interface ChangePasswordModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const ChangePasswordModal: React.FC<ChangePasswordModalProps> = ({
  isOpen,
  onClose,
}) => {
  const [oldPassword, setOldPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (newPassword !== confirmPassword) {
      setError('Les nouveaux mots de passe ne correspondent pas.');
      return;
    }

    if (newPassword.length < 6) {
      setError('Le mot de passe doit contenir au moins 6 caractères.');
      return;
    }

    try {
      setIsLoading(true);
      await changePassword({
        old_password: oldPassword,
        new_password: newPassword,
      });
      setSuccess(true);
      setTimeout(() => {
        setSuccess(false);
        onClose();
      }, 1500);
    } catch (err: any) {
      setError(
        err.response?.data?.message || 'Erreur lors du changement de mot de passe.'
      );
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4 backdrop-blur-sm"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl"
        onClick={(e) => e.stopPropagation()}
      >
        <button
          onClick={onClose}
          className="absolute right-4 top-4 rounded-md p-1 text-muted-foreground hover:bg-neutral-100"
        >
          <X className="h-4 w-4" />
        </button>

        <div className="mb-5 flex items-center gap-3 border-b border-brand-sand pb-3">
          <div className="flex h-10 w-10 items-center justify-center rounded-full bg-brand-sand text-brand-ink">
            <Lock className="h-5 w-5" />
          </div>
          <div>
            <h3 className="font-heading text-base font-bold text-brand-ink">
              Modifier le mot de passe
            </h3>
            <p className="text-[11px] text-muted-foreground">
              Choisissez un nouveau mot de passe sécurisé pour votre compte.
            </p>
          </div>
        </div>

        {success ? (
          <div className="flex flex-col items-center justify-center py-6 text-center text-emerald-600">
            <CheckCircle2 className="mb-2 h-10 w-10 animate-bounce" />
            <p className="text-sm font-bold">Mot de passe modifié avec succès !</p>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-4 text-[11px]">
            {error && (
              <div className="rounded-md bg-red-50 p-2.5 text-red-600 border border-red-200">
                {error}
              </div>
            )}

            <div>
              <label className="mb-1 block font-semibold uppercase text-[10px] tracking-wider text-muted-foreground">
                Mot de passe actuel
              </label>
              <input
                type="password"
                required
                value={oldPassword}
                onChange={(e) => setOldPassword(e.target.value)}
                className="w-full rounded-md border border-border bg-white p-2.5 outline-none focus:border-brand-violet"
              />
            </div>

            <div>
              <label className="mb-1 block font-semibold uppercase text-[10px] tracking-wider text-muted-foreground">
                Nouveau mot de passe
              </label>
              <input
                type="password"
                required
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                className="w-full rounded-md border border-border bg-white p-2.5 outline-none focus:border-brand-violet"
              />
            </div>

            <div>
              <label className="mb-1 block font-semibold uppercase text-[10px] tracking-wider text-muted-foreground">
                Confirmer le nouveau mot de passe
              </label>
              <input
                type="password"
                required
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                className="w-full rounded-md border border-border bg-white p-2.5 outline-none focus:border-brand-violet"
              />
            </div>

            <div className="flex gap-2 pt-2">
              <button
                type="button"
                onClick={onClose}
                className="flex-1 rounded-md border border-neutral-300 py-2.5 font-semibold text-neutral-600 hover:bg-brand-canvas cursor-pointer"
              >
                Annuler
              </button>
              <button
                type="submit"
                disabled={isLoading}
                className="flex-1 rounded-md bg-brand-violet py-2.5 font-semibold text-white hover:bg-brand-violet disabled:opacity-50 flex items-center justify-center gap-1.5 cursor-pointer"
              >
                {isLoading && <Loader2 className="h-3.5 w-3.5 animate-spin" />}
                Valider
              </button>
            </div>
          </form>
        )}
      </div>
    </div>
  );
};

export default ChangePasswordModal;

