import React, { useState, useEffect } from 'react';
import { Code2, Plus, X, Save, CheckCircle, Loader2, Sparkles, Briefcase } from 'lucide-react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import {
  fetchFreelanceProfile,
  updateFreelanceProfile,
  fetchServices,
  proposeService,
  fetchTechnologies,
  addTechnology,
  type ServiceData,
  type TechnologieData,
} from '../../api/freelanceApi';

interface ServicesTechTabProps {
  user?: any;
}

export const ServicesTechTab: React.FC<ServicesTechTabProps> = () => {
  const queryClient = useQueryClient();

  // ─── Real DB Queries ─────────────────────────
  const { data: profile, isLoading: isProfileLoading } = useQuery({
    queryKey: ['freelanceProfile'],
    queryFn: fetchFreelanceProfile,
  });

  const { data: availableServices = [], isLoading: isServicesLoading } = useQuery({
    queryKey: ['servicesList'],
    queryFn: fetchServices,
  });

  const { data: availableTechs = [], isLoading: isTechsLoading } = useQuery({
    queryKey: ['technologiesList'],
    queryFn: fetchTechnologies,
  });

  // ─── Local Form State initialized from DB ────
  const [selectedServiceId, setSelectedServiceId] = useState<number | null>(null);
  const [selectedTechIds, setSelectedTechIds] = useState<number[]>([]);
  const [customServiceName, setCustomServiceName] = useState('');
  const [customTechName, setCustomTechName] = useState('');
  const [showProposeService, setShowProposeService] = useState(false);
  const [showAddTech, setShowAddTech] = useState(false);
  const [savedSuccess, setSavedSuccess] = useState(false);

  useEffect(() => {
    if (profile) {
      if (profile.service) {
        setSelectedServiceId(profile.service);
      }
      if (profile.technologies) {
        setSelectedTechIds(profile.technologies);
      }
    }
  }, [profile]);

  // ─── Mutations ──────────────────────────────
  const saveMutation = useMutation({
    mutationFn: () =>
      updateFreelanceProfile({
        service: selectedServiceId,
        technologies: selectedTechIds,
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['freelanceProfile'] });
      queryClient.invalidateQueries({ queryKey: ['missions-compatibilite'] });
      setSavedSuccess(true);
      setTimeout(() => setSavedSuccess(false), 3000);
    },
  });

  const proposeServiceMutation = useMutation({
    mutationFn: (name: string) => proposeService({ name }),
    onSuccess: (newService: ServiceData) => {
      queryClient.invalidateQueries({ queryKey: ['servicesList'] });
      setSelectedServiceId(newService.id);
      setCustomServiceName('');
      setShowProposeService(false);
    },
  });

  const addTechMutation = useMutation({
    mutationFn: (name: string) => addTechnology({ name }),
    onSuccess: (newTech: TechnologieData) => {
      queryClient.invalidateQueries({ queryKey: ['technologiesList'] });
      if (!selectedTechIds.includes(newTech.id)) {
        setSelectedTechIds([...selectedTechIds, newTech.id]);
      }
      setCustomTechName('');
      setShowAddTech(false);
    },
  });

  const toggleTech = (techId: number) => {
    if (selectedTechIds.includes(techId)) {
      setSelectedTechIds(selectedTechIds.filter((id) => id !== techId));
    } else {
      setSelectedTechIds([...selectedTechIds, techId]);
    }
  };

  const handleProposeServiceSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (customServiceName.trim()) {
      proposeServiceMutation.mutate(customServiceName.trim());
    }
  };

  const handleAddTechSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (customTechName.trim()) {
      addTechMutation.mutate(customTechName.trim());
    }
  };

  if (isProfileLoading || isServicesLoading || isTechsLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="h-6 w-6 animate-spin text-brand-ink" />
      </div>
    );
  }

  return (
    <div className="rounded-2xl border border-brand-sand bg-white p-6 sm:p-8 shadow-xs max-w-3xl space-y-6 text-[11px]">
      {savedSuccess && (
        <div className="flex items-center gap-2 rounded-lg bg-emerald-50 border border-emerald-200 p-3 font-semibold text-emerald-700">
          <CheckCircle className="h-4 w-4 text-emerald-600" />
          Service principal et technologies enregistrés dans votre profil avec succès !
        </div>
      )}

      {/* ─── Section 1: Predefined Services Selection ─── */}
      <div>
        <div className="flex items-center justify-between mb-1">
          <h3 className="font-heading text-xs font-bold text-brand-ink flex items-center gap-1.5">
            <Briefcase className="h-3.5 w-3.5 text-brand-ink" /> Service Principal (Spécialité)
          </h3>
          <button
            type="button"
            onClick={() => setShowProposeService(!showProposeService)}
            className="text-[10px] font-semibold text-brand-ink hover:underline flex items-center gap-1"
          >
            <Plus className="h-3 w-3" /> Proposer un autre service
          </button>
        </div>
        <p className="text-muted-foreground mb-3">
          Sélectionnez le domaine de service géré par l'administration qui correspond le mieux à votre profil.
        </p>

        {showProposeService && (
          <form onSubmit={handleProposeServiceSubmit} className="flex gap-2 mb-3 bg-brand-canvas p-3 rounded-xl border border-border">
            <input
              type="text"
              value={customServiceName}
              onChange={(e) => setCustomServiceName(e.target.value)}
              placeholder="Nom du nouveau service à proposer (ex: IA & Machine Learning)..."
              className="flex-1 rounded-lg border border-border bg-white px-3 py-1.5 text-[11px] outline-none focus:border-brand-violet"
            />
            <button
              type="submit"
              disabled={proposeServiceMutation.isPending}
              className="inline-flex items-center gap-1 rounded-lg bg-brand-violet px-3.5 py-1.5 font-semibold text-white hover:bg-brand-violet disabled:opacity-50"
            >
              {proposeServiceMutation.isPending ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : 'Ajouter au catalogue'}
            </button>
          </form>
        )}

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
          {availableServices.map((service) => {
            const isSelected = selectedServiceId === service.id;
            return (
              <button
                type="button"
                key={service.id}
                onClick={() => setSelectedServiceId(service.id)}
                className={`flex items-center justify-between text-left p-3 rounded-xl border transition-all cursor-pointer ${
                  isSelected
                    ? 'border-brand-violet bg-brand-sand text-brand-ink font-bold shadow-xs'
                    : 'border-border bg-white text-brand-ink hover:border-neutral-300'
                }`}
              >
                <div>
                  <div className="text-[11.5px]">{service.name}</div>
                  {service.description && (
                    <div className="text-[9.5px] text-muted-foreground font-normal line-clamp-1">{service.description}</div>
                  )}
                </div>
                {isSelected && <CheckCircle className="h-4 w-4 text-brand-ink shrink-0" />}
              </button>
            );
          })}
        </div>
      </div>

      {/* ─── Section 2: Technologies Catalogue Selection ─── */}
      <div className="border-t border-brand-sand pt-6">
        <div className="flex items-center justify-between mb-1">
          <h3 className="font-heading text-xs font-bold text-brand-ink flex items-center gap-1.5">
            <Sparkles className="h-3.5 w-3.5 text-brand-violet" /> Technologies & Outils du Catalogue
          </h3>
          <button
            type="button"
            onClick={() => setShowAddTech(!showAddTech)}
            className="text-[10px] font-semibold text-brand-ink hover:underline flex items-center gap-1"
          >
            <Plus className="h-3 w-3" /> Ajouter une autre techno
          </button>
        </div>
        <p className="text-muted-foreground mb-3">
          Cochez les technologies du catalogue officiel que vous maîtrisez.
        </p>

        {showAddTech && (
          <form onSubmit={handleAddTechSubmit} className="flex gap-2 mb-3 bg-brand-canvas p-3 rounded-xl border border-border">
            <input
              type="text"
              value={customTechName}
              onChange={(e) => setCustomTechName(e.target.value)}
              placeholder="Nom de la nouvelle techno (ex: Rust, Flutter)..."
              className="flex-1 rounded-lg border border-border bg-white px-3 py-1.5 text-[11px] outline-none focus:border-brand-violet"
            />
            <button
              type="submit"
              disabled={addTechMutation.isPending}
              className="inline-flex items-center gap-1 rounded-lg bg-brand-violet px-3.5 py-1.5 font-semibold text-white hover:bg-brand-violet disabled:opacity-50"
            >
              {addTechMutation.isPending ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : 'Ajouter'}
            </button>
          </form>
        )}

        <div className="flex flex-wrap gap-2">
          {availableTechs.map((tech) => {
            const isSelected = selectedTechIds.includes(tech.id);
            return (
              <button
                type="button"
                key={tech.id}
                onClick={() => toggleTech(tech.id)}
                className={`inline-flex items-center gap-1.5 rounded-full px-3 py-1.5 text-[10.5px] font-semibold transition-all cursor-pointer border ${
                  isSelected
                    ? 'bg-brand-violet text-white border-brand-violet shadow-xs'
                    : 'bg-brand-canvas text-brand-ink border-border hover:border-neutral-300'
                }`}
              >
                {tech.imgUrl ? (
                  <img src={tech.imgUrl} alt={tech.name} className="h-3.5 w-3.5 object-contain" />
                ) : (
                  <Code2 className="h-3 w-3 text-brand-violet" />
                )}
                {tech.name}
                {isSelected ? <X className="h-3 w-3 ml-1 text-white/80 hover:text-white" /> : <Plus className="h-3 w-3 ml-0.5 text-muted-foreground" />}
              </button>
            );
          })}
        </div>
      </div>

      <div className="border-t border-brand-sand pt-4 flex justify-end">
        <button
          type="button"
          disabled={saveMutation.isPending}
          onClick={() => saveMutation.mutate()}
          className="inline-flex items-center gap-1.5 rounded-lg bg-brand-violet px-6 py-2.5 font-semibold text-white hover:bg-brand-violet cursor-pointer disabled:opacity-50"
        >
          {saveMutation.isPending ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Save className="h-3.5 w-3.5" />}
          Enregistrer les modifications
        </button>
      </div>
    </div>
  );
};

export default ServicesTechTab;

import React, { useState } from 'react';
import { AlertTriangle, X, Trash2, Loader2 } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { deleteAccount } from '../../api/userApi';

export const DangerZoneCard: React.FC = () => {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(null);

  const deleteMutation = useMutation({
    mutationFn: (pwd: string) => deleteAccount(pwd),
    onSuccess: () => {
      localStorage.removeItem('access_token');
      localStorage.removeItem('refresh_token');
      queryClient.clear();
      navigate('/login');
    },
    onError: (err: any) => {
      const msg =
        err.response?.data?.password?.[0] ||
        err.response?.data?.error ||
        err.response?.data?.detail ||
        'Erreur lors de la suppression du compte.';
      setError(typeof msg === 'string' ? msg : JSON.stringify(msg));
    },
  });

  const handleDeleteAccount = () => {
    if (!password) {
      setError('Le mot de passe est requis.');
      return;
    }
    setError(null);
    deleteMutation.mutate(password);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setPassword('');
    setError(null);
  };

  return (
    <div className="rounded-2xl border border-red-200 bg-red-50/40 p-6 sm:p-7 shadow-xs">
      <div className="flex items-start gap-4">
        <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-red-100 text-red-600">
          <AlertTriangle className="h-5 w-5" />
        </div>

        <div className="flex-1">
          <h3 className="font-heading text-sm font-bold text-brand-ink">
            Supprimer le compte
          </h3>
          <p className="mt-1 text-[11px] text-neutral-600 leading-relaxed max-w-xl">
            La suppression de votre compte est{' '}
            <span className="font-bold text-red-600">définitive</span> et entraînera la{' '}
            <span className="font-bold text-red-600">perte immédiate</span> de toutes vos
            données, candidatures et historique de missions. Cette action ne peut pas être annulée.
          </p>

          <button
            type="button"
            onClick={() => setIsModalOpen(true)}
            className="mt-4 inline-flex items-center gap-2 rounded-lg bg-red-500 px-4 py-2 text-[11px] font-bold text-white shadow-xs hover:bg-red-600 transition-colors cursor-pointer"
          >
            <Trash2 className="h-3.5 w-3.5" /> Supprimer mon compte
          </button>
        </div>
      </div>

      {/* Confirmation Modal */}
      {isModalOpen && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4 backdrop-blur-sm"
          onClick={handleCloseModal}
        >
          <div
            className="relative w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl"
            onClick={(e) => e.stopPropagation()}
          >
            <button
              onClick={handleCloseModal}
              className="absolute right-4 top-4 rounded-md p-1 text-muted-foreground hover:bg-neutral-100"
            >
              <X className="h-4 w-4" />
            </button>

            <div className="mb-4 text-center">
              <div className="mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-red-100 text-red-600">
                <AlertTriangle className="h-6 w-6" />
              </div>
              <h3 className="font-heading text-base font-bold text-brand-ink">
                Confirmer la suppression
              </h3>
              <p className="mt-1 text-[11px] text-muted-foreground">
                Pour confirmer, saisissez votre{' '}
                <span className="font-bold text-red-600">mot de passe actuel</span> ci-dessous :
              </p>
            </div>

            <div className="space-y-4 text-[11px]">
              {error && (
                <div className="rounded-md bg-red-50 p-2.5 text-red-600 border border-red-200 text-center">
                  {error}
                </div>
              )}

              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="Votre mot de passe"
                className="w-full rounded-md border border-neutral-300 px-3.5 py-2.5 outline-none focus:border-red-500 text-center font-medium"
              />

              <div className="flex gap-2">
                <button
                  type="button"
                  onClick={handleCloseModal}
                  className="flex-1 rounded-md border border-neutral-300 py-2.5 font-semibold text-neutral-600 hover:bg-brand-canvas cursor-pointer"
                >
                  Annuler
                </button>
                <button
                  type="button"
                  disabled={!password || deleteMutation.isPending}
                  onClick={handleDeleteAccount}
                  className="flex-1 rounded-md bg-red-500 py-2.5 font-bold text-white hover:bg-red-600 disabled:opacity-40 cursor-pointer flex items-center justify-center gap-1.5"
                >
                  {deleteMutation.isPending && (
                    <Loader2 className="h-3.5 w-3.5 animate-spin" />
                  )}
                  Confirmer la suppression
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default DangerZoneCard;

import React from 'react';
import { Laptop, Smartphone, Monitor, Loader2 } from 'lucide-react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import {
  fetchSessions,
  revokeSession,
  revokeAllOtherSessions,
  type SessionData,
} from '../../api/userApi';

/**
 * Parses the raw User-Agent string to extract a human-readable device name
 * and an icon type for display.
 */
function parseDevice(rawDevice: string): {
  label: string;
  iconType: 'laptop' | 'mobile' | 'desktop';
} {
  const ua = rawDevice.toLowerCase();

  if (/iphone|android|mobile/i.test(ua)) {
    const match = ua.match(/(iphone|samsung|pixel|xiaomi|huawei|android)/i);
    return {
      label: match ? match[1].charAt(0).toUpperCase() + match[1].slice(1) : 'Mobile',
      iconType: 'mobile',
    };
  }

  if (/macintosh|mac os/i.test(ua)) {
    return { label: 'Mac', iconType: 'laptop' };
  }

  if (/windows/i.test(ua)) {
    return { label: 'Windows PC', iconType: 'desktop' };
  }

  if (/linux/i.test(ua)) {
    return { label: 'Linux PC', iconType: 'desktop' };
  }

  return { label: 'Appareil inconnu', iconType: 'laptop' };
}

/**
 * Extracts browser name from a User-Agent string.
 */
function parseBrowser(rawDevice: string): string {
  if (/edg/i.test(rawDevice)) return 'Edge';
  if (/opr|opera/i.test(rawDevice)) return 'Opera';
  if (/firefox/i.test(rawDevice)) return 'Firefox';
  if (/safari/i.test(rawDevice) && !/chrome/i.test(rawDevice)) return 'Safari';
  if (/chrome/i.test(rawDevice)) return 'Chrome';
  return 'Navigateur';
}

/**
 * Formats the last active date into a human-readable French string.
 */
function formatLastActive(dateStr: string, isCurrent: boolean): string {
  if (isCurrent) return 'Actif maintenant';

  const date = new Date(dateStr);
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffMinutes = Math.floor(diffMs / 60000);
  const diffHours = Math.floor(diffMs / 3600000);
  const diffDays = Math.floor(diffMs / 86400000);

  if (diffMinutes < 1) return "À l'instant";
  if (diffMinutes < 60) return `Il y a ${diffMinutes} min`;
  if (diffHours < 24) return `Il y a ${diffHours}h`;
  if (diffDays === 1) return 'Hier';
  if (diffDays < 7) return `Il y a ${diffDays} jours`;
  return date.toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' });
}

export const SessionsManagerCard: React.FC = () => {
  const queryClient = useQueryClient();

  const {
    data: sessions = [],
    isLoading,
    isError,
  } = useQuery<SessionData[]>({
    queryKey: ['sessions'],
    queryFn: fetchSessions,
  });

  const revokeMutation = useMutation({
    mutationFn: (sessionId: number) => revokeSession(sessionId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['sessions'] });
    },
  });

  const revokeAllMutation = useMutation({
    mutationFn: () => revokeAllOtherSessions(),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['sessions'] });
    },
  });

  const getIcon = (type: string) => {
    switch (type) {
      case 'mobile':
        return <Smartphone className="h-5 w-5 text-neutral-600" />;
      case 'desktop':
        return <Monitor className="h-5 w-5 text-neutral-600" />;
      default:
        return <Laptop className="h-5 w-5 text-neutral-600" />;
    }
  };

  // The first session (ordered by -date_last_used) with the current refresh token is the current one
  const currentRefreshToken = localStorage.getItem('refresh_token');

  return (
    <div className="rounded-2xl border border-brand-sand bg-white p-6 sm:p-7 shadow-xs">
      <div className="mb-5 border-b border-brand-sand pb-4">
        <h2 className="font-heading text-sm font-bold text-brand-ink">
          Gérer ses sessions ouvertes
        </h2>
        <p className="mt-1 text-[11px] text-muted-foreground">
          Consultez et gérez les appareils connectés à votre compte.
        </p>
      </div>

      {isLoading ? (
        <div className="flex items-center justify-center py-8">
          <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
        </div>
      ) : isError ? (
        <div className="py-6 text-center text-[11px] text-red-500">
          Impossible de charger les sessions.
        </div>
      ) : sessions.length === 0 ? (
        <div className="py-6 text-center text-[11px] text-muted-foreground">
          Aucune session active.
        </div>
      ) : (
        <>
          {/* List matching Mockup */}
          <div className="space-y-3">
            {sessions.map((s, index) => {
              const { label: deviceLabel, iconType } = parseDevice(s.device || '');
              const browser = parseBrowser(s.device || '');
              // First session in the list (most recent) is considered "current"
              const isCurrent = index === 0;

              return (
                <div
                  key={s.id}
                  className="flex flex-col gap-3 rounded-xl border border-border bg-white p-4 sm:flex-row sm:items-center sm:justify-between"
                >
                  <div className="flex items-center gap-3.5">
                    <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-brand-canvas border border-border">
                      {getIcon(iconType)}
                    </div>

                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-heading text-[12px] font-bold text-brand-ink">
                          {deviceLabel} • {browser}
                        </span>
                        {isCurrent && (
                          <span className="rounded-full bg-emerald-100 px-2 py-0.5 text-[8.5px] font-bold text-emerald-700 uppercase tracking-wide">
                            CET APPAREIL
                          </span>
                        )}
                      </div>
                      <p className="text-[10.5px] text-muted-foreground">
                        {s.location || 'Localisation inconnue'} •{' '}
                        {formatLastActive(s.date_last_used, isCurrent)}
                      </p>
                    </div>
                  </div>

                  {!isCurrent && (
                    <button
                      type="button"
                      disabled={revokeMutation.isPending}
                      onClick={() => revokeMutation.mutate(s.id)}
                      className="text-[11px] font-semibold text-red-500 hover:text-red-700 cursor-pointer self-start sm:self-auto disabled:opacity-50"
                    >
                      Déconnecter
                    </button>
                  )}
                </div>
              );
            })}
          </div>

          {/* Disconnect all others action */}
          {sessions.length > 1 && (
            <div className="mt-4 pt-2 text-center">
              <button
                type="button"
                disabled={revokeAllMutation.isPending}
                onClick={() => revokeAllMutation.mutate()}
                className="text-[11px] font-semibold text-brand-ink hover:underline cursor-pointer disabled:opacity-50 inline-flex items-center gap-1.5"
              >
                {revokeAllMutation.isPending && (
                  <Loader2 className="h-3 w-3 animate-spin" />
                )}
                Déconnecter toutes les autres sessions
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
};

export default SessionsManagerCard;

