import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { useSearchParams } from 'react-router-dom';
import type { Conversation } from '../../api/message';
import getCurrentUser from '../../utils/getUser';
import { useConversions } from '../../hooks/useConversations';
import { ConversationList, ChatPanel, EmptyChat } from '../../components/messagerie';
import { ArrowLeft } from 'lucide-react';

const MessageriePage: React.FC = () => {
  const [searchParams] = useSearchParams();
  const [activeConversation, setActiveConversation] = useState<Conversation | null>(null);
  const [mobileShowChat, setMobileShowChat] = useState(false);
  const [syntheticConversation, setSyntheticConversation] = useState<Conversation | null>(null);

  const { data: user } = useQuery({
    queryKey: ['currentUser'],
    queryFn: getCurrentUser,
    retry: false,
  });

  const { data: fetchedConversations = [], isLoading: convLoading } = useConversions();

  // Combine fetched conversations with any synthetic conversation created via URL params
  const conversations = useMemo(() => {
    if (!syntheticConversation) return fetchedConversations;
    const exists = fetchedConversations.some(
      (c) => String(c.mission_id) === String(syntheticConversation.mission_id)
    );
    if (exists) return fetchedConversations;
    return [syntheticConversation, ...fetchedConversations];
  }, [fetchedConversations, syntheticConversation]);

  // Handle URL query parameters (e.g. /espace/messages?mission=12&title=Design&user_id=5&first_name=Marc)
  useEffect(() => {
    const missionId = searchParams.get('mission');
    if (!missionId) return;

    // 1. Check if conversation already exists in fetched list
    const existing = fetchedConversations.find(
      (c) => String(c.mission_id) === String(missionId)
    );

    if (existing) {
      setActiveConversation(existing);
      setMobileShowChat(true);
    } else if (missionId) {
      // 2. Synthesize a conversation from URL params so user can initiate chat immediately
      const title = searchParams.get('title') || 'Mission #' + missionId;
      const userId = Number(searchParams.get('user_id') || 0);
      const firstName = searchParams.get('first_name') || 'Collaborateur';
      const lastName = searchParams.get('last_name') || '';
      const profilePic = searchParams.get('profile_picture') || null;

      const newConv: Conversation = {
        mission_id: String(missionId),
        mission_titre: title,
        autre_utlisateur: {
          id: userId,
          first_name: firstName,
          last_name: lastName,
          profile_picture: profilePic,
        },
        dernier_message: null,
        nb_non_lus: 0,
        date_dernier_message: new Date().toISOString(),
        is_linked: true,
      };

      setSyntheticConversation(newConv);
      setActiveConversation(newConv);
      setMobileShowChat(true);
    }
  }, [searchParams, fetchedConversations]);

  const handleSelectConversation = useCallback((conv: Conversation) => {
    setActiveConversation(conv);
    setMobileShowChat(true);
  }, []);

  const handleBackToList = useCallback(() => {
    setMobileShowChat(false);
  }, []);

  return (
    <div
      className="flex h-[calc(100dvh-48px)] overflow-hidden bg-white shadow-sm -m-4 sm:-m-5 lg:-m-6"
    >
      {/* ─── Conversation List (left panel) ─── */}
      <div
        className={`
          w-full md:w-[280px] lg:w-[320px] shrink-0 border-r border-border/60
          ${mobileShowChat ? 'hidden md:flex' : 'flex'}
          flex-col
        `}
      >
        <ConversationList
          conversations={conversations}
          activeConversationId={activeConversation?.mission_id ?? null}
          onSelectConversation={handleSelectConversation}
          isLoading={convLoading}
        />
      </div>

      {/* ─── Chat Panel (right panel) ─── */}
      <div
        className={`
          flex-1 min-w-0 flex flex-col
          ${!mobileShowChat ? 'hidden md:flex' : 'flex'}
        `}
      >
        {/* Mobile back button */}
        {mobileShowChat && (
          <button
            type="button"
            onClick={handleBackToList}
            className="md:hidden flex items-center gap-2 px-3 py-2 text-[12px] font-medium text-brand-ink bg-white border-b border-border shrink-0 cursor-pointer hover:bg-brand-canvas transition-colors"
          >
            <ArrowLeft className="w-4 h-4" />
            Retour aux conversations
          </button>
        )}

        {activeConversation && user ? (
          <ChatPanel
            conversation={activeConversation}
            currentUser={user}
          />
        ) : (
          <EmptyChat />
        )}
      </div>
    </div>
  );
};

export default MessageriePage;

import React, { useEffect, useState } from "react";
import {
  useQueryClient,
  useMutation as useReactMutation,
  useQuery as useReactQuery,
} from "@tanstack/react-query";
import {
  ArrowLeft,
  CalendarDays,
  Check,
  Code2,
  Loader2,
  Plus,
  Sparkles,
  WalletCards,
  X,
} from "lucide-react";
import { useNavigate, useParams } from "react-router-dom";
import {
  createMission,
  generateMissionDescription,
  getMission,
  getMissionServices,
  type MissionPayload,
  type PaymentOperator,
  updateMission,
} from "../../api/missionsApi";
import { fetchTechnologies } from "../../api/freelanceApi";
import { getErrorMessage } from "../../utils/errorMessage";
import {
  getTodayDate,
  MissionValidation,
  MissionTitleValidation,
  type MissionFormErrors,
} from "../../validations/missionValidation";

const initialForm: MissionPayload = {
  title: "",
  description: "",
  date_deadline: "",
  operateurMobileMoney: "WAVE",
  budget: 0,
  service: 0,
  technologies: [],
};

const inputClass =
  "w-full rounded-md border border-border bg-white px-3 py-2.5 text-[12px] text-[#252525] outline-none transition focus:border-brand-violet focus:ring-2 focus:ring-brand-violet/10";

const MissionFormPage: React.FC = () => {
  const navigate = useNavigate();
  const { missionId } = useParams();
  const queryClient = useQueryClient();
  const [form, setForm] = useState<MissionPayload>(initialForm);
  const [selectedTechs, setSelectedTechs] = useState<number[]>([]);
  const [error, setError] = useState("");
  const [fieldErrors, setFieldErrors] = useState<MissionFormErrors>({});

  const fieldError = (field: keyof MissionFormErrors) => fieldErrors[field] ? (
    <p id={`${field}-error`} role="alert" className="mt-1 text-[11px] text-red-600">
      {fieldErrors[field]}
    </p>
  ) : null;

  const fieldAccessibility = (field: keyof MissionFormErrors) => ({
    "aria-invalid": Boolean(fieldErrors[field]),
    "aria-describedby": fieldErrors[field] ? `${field}-error` : undefined,
  });

  const servicesQuery = useReactQuery({
    queryKey: ["mission-services"],
    queryFn: getMissionServices,
  });

  const techsQuery = useReactQuery({
    queryKey: ["technologiesList"],
    queryFn: fetchTechnologies,
  });

  const missionQuery = useReactQuery({
    queryKey: ["mission", missionId],
    queryFn: () => getMission(Number(missionId)),
    enabled: Boolean(missionId),
  });

  useEffect(() => {
    if (missionQuery.data) {
      setForm({
        title: missionQuery.data.title,
        description: missionQuery.data.description,
        date_deadline: missionQuery.data.date_deadline || "",
        operateurMobileMoney: missionQuery.data.operateurMobileMoney,
        budget: missionQuery.data.budget,
        service: missionQuery.data.service,
        technologies: missionQuery.data.technologies || [],
      });
      if (missionQuery.data.technologies) {
        setSelectedTechs(missionQuery.data.technologies);
      }
    }
  }, [missionQuery.data]);

  const createMutation = useReactMutation({
    mutationFn: (payload: MissionPayload) =>
      missionId
        ? updateMission({ id: Number(missionId), payload })
        : createMission(payload),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["missions"] });
      navigate("/espace/mes-annonces");
    },
    onError: (mutationError) => {
      setError(
        getErrorMessage(mutationError, "Impossible de publier l'annonce.")
      );
    },
  });

  const generateDescriptionMutation = useReactMutation({
    mutationFn: (title: string) => generateMissionDescription(title),
    onSuccess: (generatedDescription) => {
      updateField("description", generatedDescription);
    },
    onError: (mutationError) => {
      setError(
        getErrorMessage(
          mutationError,
          "La génération de la description a échoué."
        )
      );
    },
  });

  const updateField = <K extends keyof MissionPayload>(
    field: K,
    value: MissionPayload[K]
  ) => {
    setForm((current) => ({ ...current, [field]: value }));
    setFieldErrors((current) => ({ ...current, [field]: undefined }));
    setError("");
  };

  const toggleTech = (techId: number) => {
    setFieldErrors((current) => ({ ...current, technologies: undefined }));
    if (selectedTechs.includes(techId)) {
      setSelectedTechs(selectedTechs.filter((id) => id !== techId));
    } else {
      setSelectedTechs([...selectedTechs, techId]);
    }
  };

  const submit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (createMutation.isPending || generateDescriptionMutation.isPending) return;
    setError("");
    const result = MissionValidation.safeParse({
      ...form,
      technologies: selectedTechs,
    });
    if (!result.success) {
      const errors: MissionFormErrors = {};
      for (const issue of result.error.issues) {
        const field = issue.path[0] as keyof MissionFormErrors;
        if (!errors[field]) errors[field] = issue.message;
      }
      setFieldErrors(errors);
      return;
    }
    setFieldErrors({});
    createMutation.mutate(result.data);
  };

  return (
    <div className="mx-auto max-w-[760px] pb-8">
      <button
        type="button"
        onClick={() => navigate("/espace/mes-annonces")}
        className="mb-4 inline-flex items-center gap-2 text-[11px] font-medium text-muted-foreground hover:text-brand-ink"
      >
        <ArrowLeft className="h-3.5 w-3.5" /> Retour à mes annonces
      </button>

      <form
        noValidate
        onSubmit={submit}
        className="overflow-hidden rounded-lg border border-brand-sand bg-white shadow-[0_8px_30px_rgba(31,42,48,0.04)]"
      >
        <div className="border-b border-brand-sand px-5 py-4 sm:px-7">
          <p className="mb-1 text-[10px] font-semibold uppercase tracking-[0.16em] text-brand-violet">
            Nouvelle annonce
          </p>
          <h1 className="font-heading text-xl font-semibold tracking-tight text-[#20252a]">
            Détails de l'annonce
          </h1>
          <p className="mt-1 text-[11px] text-muted-foreground">
            Présentez clairement votre besoin et les technologies requises pour
            attirer les bons profils.
          </p>
        </div>

        <div className="space-y-5 px-5 py-6 sm:px-7">
          <label className="block">
            <span className="mb-1.5 block text-[11px] font-semibold text-brand-ink">
              Titre de l'annonce <span className="text-brand-violet">*</span>
            </span>
            <input
              {...fieldAccessibility("title")}
              className={inputClass}
              value={form.title}
              onChange={(event) => updateField("title", event.target.value)}
              placeholder="Ex : Développeur Full-Stack pour refonte de site"
              maxLength={100}
            />
            {fieldError("title")}
          </label>

          <label className="block">
            <div className="mb-1.5 flex flex-wrap items-center justify-between gap-2">
              <span className="text-[11px] font-semibold text-brand-ink">
                Description <span className="text-brand-violet">*</span>
              </span>
              <div className="flex items-center gap-3">
                <button
                  type="button"
                  disabled={
                    generateDescriptionMutation.isPending || !form.title.trim()
                  }
                  onClick={() => {
                    const result = MissionTitleValidation.safeParse(form.title);
                    if (!result.success) {
                      setFieldErrors((current) => ({
                        ...current,
                        title: result.error.issues[0].message,
                      }));
                      return;
                    }
                    setError("");
                    generateDescriptionMutation.mutate(result.data);
                  }}
                  className="inline-flex items-center gap-1.5 rounded-full bg-brand-ink px-3 py-1 text-[10px] font-semibold text-brand-green transition hover:bg-brand-ink/85 disabled:cursor-not-allowed disabled:opacity-50 cursor-pointer shadow-xs"
                  title={
                    !form.title.trim()
                      ? "Saisissez un titre pour générer une description par l'IA"
                      : "Générer la description automatiquement via l'IA"
                  }
                >
                  {generateDescriptionMutation.isPending ? (
                    <Loader2 className="h-3 w-3 animate-spin text-brand-green" />
                  ) : (
                    <Sparkles className="h-3 w-3 text-brand-green" />
                  )}
                  <span>
                    {generateDescriptionMutation.isPending
                      ? "Génération en cours..."
                      : "Générer avec l'IA"}
                  </span>
                </button>
                <span className="text-[10px] text-muted-foreground">
                  {form.description.length} / 1000 caractères
                </span>
              </div>
            </div>
            <textarea
              {...fieldAccessibility("description")}
              className={`${inputClass} min-h-[140px] resize-y`}
              value={form.description}
              onChange={(event) =>
                updateField("description", event.target.value)
              }
              placeholder="Décrivez votre projet en détail... Ou saisissez un titre et cliquez sur 'Générer avec l'IA'."
              maxLength={1000}
            />
            {fieldError("description")}
          </label>

          <div className="grid gap-4 sm:grid-cols-2">
            <label className="block">
              <span className="mb-1.5 block text-[11px] font-semibold text-brand-ink">
                Budget estimé <span className="text-brand-violet">*</span>
              </span>
              <div className="relative">
                <input
                  className={`${inputClass} pr-16`}
                  type="number"
                  {...fieldAccessibility("budget")}
                  min="1"
                  step="1"
                  value={form.budget || ""}
                  onChange={(event) =>
                    updateField("budget", Number(event.target.value))
                  }
                  placeholder="0"
                />
                <span className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-[10px] font-medium text-muted-foreground">
                  FCFA
                </span>
              </div>
              {fieldError("budget")}
            </label>
            <label className="block">
              <span className="mb-1.5 block text-[11px] font-semibold text-brand-ink">
                Date limite <span className="text-brand-violet">*</span>
              </span>
              <div className="relative">
                <input
                  className={`${inputClass} pr-9`}
                  type="date"
                  {...fieldAccessibility("date_deadline")}
                  min={getTodayDate()}
                  value={form.date_deadline}
                  onChange={(event) =>
                    updateField("date_deadline", event.target.value)
                  }
                />
                <CalendarDays className="pointer-events-none absolute right-3 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-muted-foreground" />
              </div>
              {fieldError("date_deadline")}
            </label>
          </div>

          {/* Service Requis */}
          <div>
            <div className="mb-2 flex items-center justify-between">
              <span className="text-[11px] font-semibold text-brand-ink">
                Service requis <span className="text-brand-violet">*</span>
              </span>
              <span className="text-[10px] text-muted-foreground">
                Un service par annonce
              </span>
            </div>
            {servicesQuery.isLoading ? (
              <div className="text-[11px] text-muted-foreground">
                Chargement des services...
              </div>
            ) : (
              <div className="flex flex-wrap gap-2">
                {servicesQuery.data?.map((service) => (
                  <button
                    key={service.id}
                    {...fieldAccessibility("service")}
                    type="button"
                    onClick={() => updateField("service", service.id)}
                    className={`inline-flex items-center gap-1.5 rounded-full border px-3 py-1.5 text-[10px] font-medium transition cursor-pointer ${
                      form.service === service.id
                        ? "border-brand-violet bg-brand-violet text-white"
                        : "border-border bg-white text-neutral-600 hover:border-brand-violet"
                    }`}
                  >
                    {form.service === service.id && (
                      <Check className="h-3 w-3" />
                    )}
                    {service.name}
                  </button>
                ))}
              </div>
            )}
            {fieldError("service")}
          </div>

          {/* Technologies Requises */}
          <div>
            <div className="mb-2 flex items-center justify-between">
              <span className="text-[11px] font-semibold text-brand-ink">
                Technologies & Stack Requis
              </span>
              <span className="text-[10px] text-muted-foreground">
                Sélectionnez les technologies utiles (facultatif)
              </span>
            </div>
            {techsQuery.isLoading ? (
              <div className="text-[11px] text-muted-foreground">
                Chargement des technologies...
              </div>
            ) : (
              <div className="flex flex-wrap gap-2">
                {techsQuery.data?.map((tech) => {
                  const isSelected = selectedTechs.includes(tech.id);
                  return (
                    <button
                      key={tech.id}
                      {...fieldAccessibility("technologies")}
                      type="button"
                      onClick={() => toggleTech(tech.id)}
                      className={`inline-flex items-center gap-1.5 rounded-full border px-3 py-1 text-[10px] font-semibold transition cursor-pointer ${
                        isSelected
                          ? "border-brand-violet bg-brand-violet text-white shadow-xs"
                          : "border-border bg-white text-brand-ink hover:border-neutral-400"
                      }`}
                    >
                      {tech.imgUrl ? (
                        <img
                          src={tech.imgUrl}
                          alt={tech.name}
                          className="h-3 w-3 object-contain"
                        />
                      ) : (
                        <Code2 className="h-3 w-3 text-brand-violet" />
                      )}
                      {tech.name}
                      {isSelected ? (
                        <X className="h-3 w-3 ml-0.5 text-white/80" />
                      ) : (
                        <Plus className="h-3 w-3 ml-0.5 text-muted-foreground" />
                      )}
                    </button>
                  );
                })}
              </div>
            )}
            {fieldError("technologies")}
          </div>

          <div>
            <span className="mb-2 block text-[11px] font-semibold text-brand-ink">
              Mode de paiement souhaité
            </span>
            <div className="grid gap-3 sm:grid-cols-2">
              {(
                [
                  ["WAVE", "Wave", "bg-brand-canvas"],
                  ["OM", "Orange Money", "bg-brand-peach"],
                ] as const
              ).map(([value, label, color]) => (
                <button
                  key={value}
                  {...fieldAccessibility("operateurMobileMoney")}
                  type="button"
                  onClick={() =>
                    updateField(
                      "operateurMobileMoney",
                      value as PaymentOperator
                    )
                  }
                  className={`relative flex items-center gap-3 rounded-md border p-3 text-left transition cursor-pointer ${
                    form.operateurMobileMoney === value
                      ? "border-brand-violet ring-1 ring-brand-violet"
                      : "border-border hover:border-border"
                  }`}
                >
                  <span
                    className={`flex h-8 w-8 items-center justify-center rounded-full ${color}`}
                  >
                    <WalletCards className="h-4 w-4 text-brand-ink" />
                  </span>
                  <span className="text-[11px] font-semibold text-brand-ink">
                    {label}
                  </span>
                  {form.operateurMobileMoney === value && (
                    <Check className="absolute right-3 h-3.5 w-3.5 text-brand-ink" />
                  )}
                </button>
              ))}
            </div>
            {fieldError("operateurMobileMoney")}
          </div>

          {(error || servicesQuery.isError) && (
            <p role="alert" className="rounded-md bg-red-50 px-3 py-2 text-[11px] text-red-600">
              {error || "Impossible de charger les services."}
            </p>
          )}
        </div>

        <div className="flex flex-col-reverse items-stretch justify-between gap-3 border-t border-brand-sand bg-brand-canvas px-5 py-4 sm:flex-row sm:items-center sm:px-7">
          <button
            type="button"
            onClick={() => navigate("/espace/mes-annonces")}
            className="text-[11px] font-medium text-muted-foreground hover:text-brand-ink cursor-pointer"
          >
            Annuler
          </button>
          <button
            disabled={createMutation.isPending || generateDescriptionMutation.isPending}
            className="inline-flex items-center justify-center gap-2 rounded-md bg-brand-green px-5 py-2.5 text-[11px] font-semibold text-brand-ink shadow-sm transition hover:bg-brand-green-hover disabled:cursor-not-allowed disabled:opacity-60 cursor-pointer"
          >
            {createMutation.isPending && (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            )}{" "}
            Publier l'annonce
          </button>
        </div>
      </form>
    </div>
  );
};

